usage:
// Client-side probe: would using a CHARGED respawn anchor at pos explode it?
// Only symbols verified against the 26.2 jars in this run are used.
//
// Why not just call RespawnAnchorBlock.canSetSpawn: it needs a ServerLevel, and its
// body (level.environmentAttributes().getValue(RESPAWN_ANCHOR_WORKS, pos)) does compile
// against a ClientLevel but always yields the attribute default false, because
// RESPAWN_ANCHOR_WORKS is not .syncable() and DimensionType reaches the client through
// DimensionType.NETWORK_CODEC -> EnvironmentAttributeMap.NETWORK_CODEC -> filterSyncable.

import net.minecraft.client.Minecraft;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.attribute.EnvironmentAttributes;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.RespawnAnchorBlock;
import net.minecraft.world.level.block.state.BlockState;

public final class AnchorProbe {

    /** Charge level 0..4, straight off the client's own blockstate copy. */
    public static int charges(BlockState state) {
        return state.getValue(RespawnAnchorBlock.CHARGE);
    }

    public static boolean isChargeable(BlockState state) {
        // canBeCharged is private static; this is its exact check.
        return charges(state) < RespawnAnchorBlock.MAX_CHARGES;
    }

    /** True if using this anchor here would explode instead of setting spawn. */
    public static boolean wouldExplode(ClientLevel level, BlockPos pos, BlockState state) {
        if (charges(state) == 0) {
            return false; // useWithoutItem returns PASS at charge 0 - nothing happens.
        }
        return !anchorWorksHere(level, pos);
    }

    private static boolean anchorWorksHere(ClientLevel level, BlockPos pos) {
        Minecraft mc = Minecraft.getInstance();
        if (mc.hasSingleplayerServer()) {
            // Authoritative. Note: this ServerLevel is owned by the integrated server
            // thread - read-only probe only, never call this from a render callback.
            ServerLevel serverLevel = mc.getSingleplayerServer().getLevel(level.dimension());
            if (serverLevel != null) {
                return RespawnAnchorBlock.canSetSpawn(serverLevel, pos);
            }
        }

        // Multiplayer fallback. FAST_LAVA is .notPositional().syncable(), so it both
        // survives the network codec and is legal via getDimensionValue (RESPAWN_ANCHOR_WORKS
        // is positional and would throw IllegalStateException in a dev client). In vanilla
        // DimensionTypes.bootstrap, only minecraft:the_nether sets FAST_LAVA true - the same
        // dimension that is the only one setting RESPAWN_ANCHOR_WORKS true.
        if (level.environmentAttributes().getDimensionValue(EnvironmentAttributes.FAST_LAVA)) {
            return true;
        }
        return level.dimension() == Level.NETHER;
    }

    /** Blast radius the explosion would use - fixed, not scaled by charge level. */
    public static float explosionPower() {
        return 5.0F; // RespawnAnchorBlock.explode: level.explode(..., 5.0F, true, BLOCK)
    }
}
